UPDATE lessons SET title='Year 3, Week 5, Lesson 1: Summarising a story', data=json_patch(data,'{"child_mission":"Summarise a story by keeping character, problem, action and outcome in your own words.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Which detail is essential in \"Raj lost his library card, checked his bag, found it in his jacket and borrowed a book\"?\nCOMPARE: Losing then finding the card and borrowing a book are essential; the jacket pocket is optional detail.\n2. Paraphrase \"found it in his jacket\" without copying those words.\nCOMPARE: Example: \"He discovered the card inside his coat.\" Meaning stays true.\n3. Order these: found the card; lost the card; borrowed a book.\nCOMPARE: Lost; found; borrowed.\n4. Name one detail you would omit from a picnic story about rain and explain why.\nCOMPARE: Weather that does not change the problem can often be shortened; the rain that ends the picnic usually cannot.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nRead or listen to a short story of at least 150 words. Identify character, problem, response and outcome; write a three-sentence summary in your own words; justify one minor detail you omitted.","interactive_activities":null,"learning_area":"English","learning_intention":"Summarise a story by keeping character, problem, action and outcome in your own words.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-RECOM-01"],"parent_notes":"Parent: Marking guidance for the independent task: Read or listen to a short story of at least 150 words. Identify character, problem, response and outcome; write a three-sentence summary in your own words; justify one minor detail you omitted. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using summary on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: A summary is shorter than the original and does not invent feelings.. Correction: Losing then finding the card and borrowing a book are essential;. Why it helps the audience is stated.\n\nParent: Likely misconception: A summary is shorter than the original and does not invent feelings. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating summary on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with summary, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about summary with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for summary. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":3,"explanation":"This matches the taught method for summary. The other choices miss a key step or use a common mistake.","options":["A summary is shorter than the original and does not invent feelings","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson","Losing then finding the card and borrowing a book are essential"],"question":"Paraphrase \"found it in his jacket\" without copying those words. Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for summary; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Losing then finding the card and borrowing a book are essential","Careful use of paraphrase and point to the words or eve with clear evidence","A summary is shorter than the original and does not invent feelings","Summarise a story by keeping character, problem, action and outcome in your own words"],"question":"Which statement is a common mistake when working with summary?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and a named paraphrase and point to the words or eve, not by copying the model. The other choices miss a key step or use a common mistake.","options":["A summary is shorter than the original and does not invent feelings","Name paraphrase and point to the words or eve only, without linking it to summary","Apply summary to new material and name the paraphrase and point to the words or eve used","Repeat the worked example wording with no new evidence"],"question":"Which response best applies summary with new evidence?","type":"multiple_choice"},{"correct_index":0,"explanation":"The skill is shown by quoting or pointing to wording that carries summary. The other choices miss a key step or use a common mistake.","options":["Point to exact words in the sentence that show summary and say what they do","Ignore the sentence and invent a more exciting event","Say the writing is good without naming any words","A summary is shorter than the original and does not invent feelings"],"question":"Read: \"Beside the oval, Kai practised bowling until the sun slipped low.\" Which choice best uses summary from this lesson?","type":"multiple_choice"},{"correct_index":0,"explanation":"The correct statement applies the language skill with textual evidence. The other choices miss a key step or use a common mistake.","options":["Losing then finding the card and borrowing a book are essential","A summary is shorter than the original and does not invent feelings","Copy a model sentence from another story unchanged","Name paraphrase and point to the words or eve without linking it to any words in the text"],"question":"Which statement correctly applies the lesson idea about summary?","type":"multiple_choice"},{"correct_index":1,"explanation":"Start from a specific textual clue, then explain its effect. The other choices miss a key step or use a common mistake.","options":["Lengthen the answer with adjectives while keeping the same idea","Locate a specific word, phrase or structural clue before deciding","Guess from the title alone with no textual clue","Copy a model sentence from another story unchanged"],"question":"In a new text, what should you do first to analyse paraphrase and point to the words or eve?","type":"multiple_choice"},{"correct_index":1,"explanation":"Repair means fixing meaning or evidence, not padding. The other choices miss a key step or use a common mistake.","options":["Delete the evidence that disagreed with your first guess","Change the inaccurate idea or missing evidence, not only the length","Add adjectives without fixing the wrong idea","Make the answer longer while keeping the same mistake"],"question":"Which revision actually improves meaning for summary?","type":"multiple_choice"},{"correct_index":0,"explanation":"Accurate transfer needs fresh material with an explained language choice. The other choices miss a key step or use a common mistake.","options":["Use a fresh sentence or text and explain one precise choice about summary","Retype the worked model as the final answer","Change fonts and claim the work is new","A summary is shorter than the original and does not invent feelings"],"question":"Which response shows accurate use of summary on fresh material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about summary with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating summary on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using summary on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for summary. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with summary, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: A summary is shorter than the original and does not invent feelings.. Correction: Losing then finding the card and borrowing a book are essential;. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w05-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise summary.","Read the mission before you start writing or speaking.","Your goal is: Summarise a story by keeping character, problem, action and outcome in your own words."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: Example: \"He discovered the card inside his coat.\" Meaning stays true."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: Story: \"Hana missed her bus, called her aunt and caught the next service.\" Summary: \"After missing the bus, Hana arranged help and travelled"],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Beginning with the ending leaves the problem unexplained."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Summarise a story by keeping character, problem, action and outcome in your own words."],"teach0":["Focus on find the essential parts.","Hold this teaching point: A summary keeps the main character, problem, important action and outcome. It leaves out decoration.","Worked comparison: Losing then finding the card and borrowing a book are essential; the jacket pocket is optional detail."],"teach1":["Focus on use your own words.","Hold this teaching point: Paraphrase shows understanding. Keep the same meaning while changing the wording.","Worked comparison: Example: \"He discovered the card inside his coat.\" Meaning stays true."],"teach2":["Focus on keep a logical order.","Hold this teaching point: Summaries usually follow the story order: problem, response, outcome.","Worked comparison: Lost; found; borrowed."],"teach3":["Focus on justify one omitted detail.","Hold this teaching point: Explain why a left-out detail was not needed for the main meaning.","Worked comparison: Weather that does not change the problem can often be shortened; the rain that ends the picnic usually cannot."],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Read or listen to a short story of at least 150 words. Identify character, problem, response and outcome; write a three-sentence summary in your own words; just"]},"subject":"English","success_criteria":["I can use summary with a specific example from this lesson.","I can identify paraphrase and point to the words or events that support it.","I can practise essential independently on a new prompt.","I can notice omit needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Copy every sentence exactly without explaining it","Add a made-up event and describe it as a fact","Ignore the task and choose an unrelated detail","Use the example and explain the clue or language choice before trying summary independently"],"question":"Which choice best applies this lesson idea about summary with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nStory: \"Hana missed her bus, called her aunt and caught the next service.\" Summary: \"After missing the bus, Hana arranged help and travelled later.\"\n\nYOUR SMALL TRY\nWhich detail is essential in \"Raj lost his library card, checked his bag, found it in his jacket and borrowed a book\"?\n\nCOMPARE AND CORRECT\nLosing then finding the card and borrowing a book are essential; the jacket pocket is optional detail.","explain":"A summary keeps the main character, problem, important action and outcome. It leaves out decoration.\n\nA summary keeps the main character, problem, important action and outcome. It leaves out decoration. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA summary is shorter than the original and does not invent feelings. Re-read the prompt and correct the misunderstanding before moving on.","title":"Find the essential parts","visual":[{"alt":"Essential summary events kept beside an omitted bag colour detail.","caption":"A summary keeps problem and outcome, not every decoration.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Keep</text><text x=\"28\" y=\"78\">missed bus, got help</text><text x=\"358\" y=\"42\">Omit</text><text x=\"358\" y=\"78\">colour of Hana bag</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Story: \"Hana missed her bus, called her aunt and caught the next service.\" Summary: \"After missing the bus, Hana arrange Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: Story: \"Hana missed her bus, called her aunt and caught the next service.\" Summary: \"After missing the bus, Hana arrange Then write your own attempt."}}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying paraphrase independently","Copy every sentence exactly without explaining it","Add a made-up event and describe it as a fact","Ignore the task and choose an unrelated detail"],"question":"Which choice best applies this lesson idea about summary with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nInstead of copying \"caught the next service\", I write \"travelled later on another bus.\"\n\nYOUR SMALL TRY\nParaphrase \"found it in his jacket\" without copying those words.\n\nCOMPARE AND CORRECT\nExample: \"He discovered the card inside his coat.\" Meaning stays true.","explain":"Paraphrase shows understanding. Keep the same meaning while changing the wording.\n\nParaphrase shows understanding. Keep the same meaning while changing the wording. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nCopying every sentence is not summarising. Re-read the prompt and correct the misunderstanding before moving on.","title":"Use your own words","visual":[{"alt":"Original wording paraphrased as travelled later on another bus.","caption":"Paraphrase keeps meaning while changing the words.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Original</text><text x=\"28\" y=\"78\">caught the next service</text><text x=\"358\" y=\"42\">Paraphrase</text><text x=\"358\" y=\"78\">travelled later on another bus</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying essential independently","Copy every sentence exactly without explaining it","Add a made-up event and describe it as a fact","Ignore the task and choose an unrelated detail"],"question":"Which choice best applies this lesson idea about summary with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nFirst Hana misses the bus; then she gets help; finally she travels later. Reversing the ending would confuse a reader.\n\nYOUR SMALL TRY\nOrder these: found the card; lost the card; borrowed a book.\n\nCOMPARE AND CORRECT\nLost; found; borrowed.","explain":"Summaries usually follow the story order: problem, response, outcome.\n\nSummaries usually follow the story order: problem, response, outcome. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nBeginning with the ending leaves the problem unexplained. Re-read the prompt and correct the misunderstanding before moving on.","title":"Keep a logical order"},{"check":{"correct_index":2,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Ignore the task and choose an unrelated detail","Copy every sentence exactly without explaining it","Use the example and explain the clue or language choice before trying omit independently","Add a made-up event and describe it as a fact"],"question":"Which choice best applies this lesson idea about summary with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI omit the jacket because the important event is recovering the card, not the exact pocket.\n\nYOUR SMALL TRY\nName one detail you would omit from a picnic story about rain and explain why.\n\nCOMPARE AND CORRECT\nWeather that does not change the problem can often be shortened; the rain that ends the picnic usually cannot.","explain":"Explain why a left-out detail was not needed for the main meaning.\n\nExplain why a left-out detail was not needed for the main meaning. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nOmitting the main problem makes the summary incomplete. Re-read the prompt and correct the misunderstanding before moving on.","title":"Justify one omitted detail"}],"title":"Year 3, Week 5, Lesson 1: Summarising a story","unit_number":1,"unit_title":"Narrative: story elements and planning","week":5,"week_in_unit":5,"word_challenges":null,"worked_example":"I DO — Story: \"Hana missed her bus, called her aunt and caught the next service.\" Summary: \"After missing the bus, Hana arranged help and travelled later.\"\n\nNow look for the exact evidence in the words or actions. Instead of copying \"caught the next service\", I write \"travelled later on another bus.\"","worked_visuals":[{"alt":"Essential summary events kept beside an omitted bag colour detail.","caption":"A summary keeps problem and outcome, not every decoration.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Keep</text><text x=\"28\" y=\"78\">missed bus, got help</text><text x=\"358\" y=\"42\">Omit</text><text x=\"358\" y=\"78\">colour of Hana bag</text></g></svg>"},{"alt":"Original wording paraphrased as travelled later on another bus.","caption":"Paraphrase keeps meaning while changing the words.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Original</text><text x=\"28\" y=\"78\">caught the next service</text><text x=\"358\" y=\"42\">Paraphrase</text><text x=\"358\" y=\"78\">travelled later on another bus</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w05-l1' AND family_id IS NULL;
